 1	/**
 2	 * Cron-style trigger for the digest job.
 3	 *
 4	 * Owner D. The route is a trigger, not the job: `runDigestEmailJob` decides
 5	 * which organizations are due based on their `digestHourUtc`, so calling this
 6	 * every hour is correct and calling it twice in one hour is harmless.
 7	 *
 8	 * Must call (do not reimplement): runDigestEmailJob
 9	 */
10	
11	import { assertCronSecret, errorResponse } from "@/app/api/_lib/responses";
12	import { runDigestEmailJob } from "@/server/jobs/digest-email-job";
13	
14	export const dynamic = "force-dynamic";
15	
16	export async function POST(request: Request): Promise<Response> {
17	  try {
18	    assertCronSecret(request);
19	
20	    const result = await runDigestEmailJob(new Date());
21	    return Response.json(result);
22	  } catch (error) {
23	    return errorResponse(error);
24	  }
25	}
 1	/**
 2	 * Builds and 'sends' the daily digest for every subscriber of every org whose digest hour has arrived.
 3	 *
 4	 * Must call (do not reimplement): isEnabled, buildDigest, sendEmail
 5	 */
 6	import { isEnabled } from "@/lib/feature-flags";
 7	import { createLogger } from "@/lib/logger";
 8	import * as notificationRepo from "@/server/repositories/notification-repository";
 9	import * as orgRepo from "@/server/repositories/organization-repository";
10	import * as usageRepo from "@/server/repositories/usage-repository";
11	import * as userRepo from "@/server/repositories/user-repository";
12	import { buildDigest, listDigestRecipients, renderDigest } from "@/server/services/digest-service";
13	import { sendEmail } from "@/server/services/email-service";
14	import { buildFlagContext } from "@/server/services/feature-flag-service";
15	import { toIsoTimestamp } from "@/types/common";
16	import { runJob } from "./types";
17	import type { JobResult } from "@/server/jobs/types";
18	import type { Organization } from "@/types/organization";
19	
20	const ORG_BATCH = 50;
21	const MS_PER_DAY = 24 * 60 * 60 * 1000;
22	
23	const logger = createLogger("digest-email-job");
24	
25	/**
26	 * One pass per scheduler tick. Each org is only processed during the UTC hour
27	 * it configured, so a tick that runs every few minutes still sends exactly one
28	 * digest per day per recipient.
29	 */
30	export async function runDigestEmailJob(now: Date): Promise<JobResult> {
31	  return runJob("digest-email", async (result) => {
32	    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);
33	
34	    for (const orgId of orgIds) {
35	      const org = await orgRepo.findOrgById(orgId);
36	      if (!org || !shouldRunForOrg(org, now)) continue;
37	
38	      if (!isEnabled("digest_email", buildFlagContext(null, org))) continue;
39	
40	      const windowEnd = toIsoTimestamp(now);
41	      const windowStart = toIsoTimestamp(new Date(now.getTime() - MS_PER_DAY));
42	
43	      for (const recipientId of await listDigestRecipients(orgId)) {
44	        try {
45	          const bundle = await buildDigest(
46	            orgId,
47	            recipientId,
48	            windowStart,
49	            windowEnd,
50	          );
51	          if (!bundle) continue;
52	
53	          const recipient = await userRepo.findUserById(recipientId);
54	          if (!recipient) continue;
55	
56	          const rendered = await renderDigest(bundle, recipient);
57	          await sendEmail({ to: recipient.email, ...rendered });
58	
59	          // Once digested, these notifications are no longer "unread" — this
60	          // is what keeps a later run inside the same window from sending
61	          // the same digest twice.
62	          for (const entry of bundle.entries) {
63	            await notificationRepo.markRead(orgId, entry.notificationId, windowEnd);
64	          }
65	
66	          result.processed += 1;
67	        } catch (error) {
68	          result.failed += 1;
69	          logger.error("digest failed", {
70	            orgId,
71	            recipientId,
72	            reason: error instanceof Error ? error.message : String(error),
73	          });
74	        }
75	      }
76	    }
77	  });
78	}
79	
80	/**
81	 * True during the org's configured digest hour. Exported because the schedule
82	 * decision is worth testing on its own, without a database.
83	 */
84	export function shouldRunForOrg(org: Organization, now: Date): boolean {
85	  if (org.archivedAt !== null) return false;
86	  return now.getUTCHours() === org.settings.digestHourUtc;
87	}
 1	/**
 2	 * Interval-based scheduler started from `src/instrumentation.ts`; decides which job kind is due.
 3	 */
 4	import { createLogger } from "@/lib/logger";
 5	import { drain, enqueue, pendingCount } from "./queue";
 6	import { toIsoTimestamp } from "@/types/common";
 7	import type { JobKind } from "./queue";
 8	
 9	/** How often `tick()` runs once the scheduler is started. */
10	const TICK_INTERVAL_MS = 60_000;
11	
12	/** Minimum gap between two runs of the same job kind, in minutes. */
13	const CADENCE_MINUTES: Readonly<Record<JobKind, number>> = {
14	  "digest-email": 60,
15	  "overdue-issues": 60,
16	  "webhook-delivery": 1,
17	  "usage-rollup": 15,
18	  "search-reindex": 1_440,
19	  "cleanup-archived": 1_440,
20	  "trial-expiry": 360,
21	};
22	
23	const logger = createLogger("job-scheduler");
24	
25	let timer: ReturnType<typeof setInterval> | null = null;
26	const lastRunAt = new Map<JobKind, number>();
27	
28	/**
29	 * Starts the interval. Idempotent, and `unref()`ed so a pending tick never
30	 * keeps a process alive — a scheduler that blocks shutdown is worse than one
31	 * that misses the last tick.
32	 */
33	export function startScheduler(): void {
34	  if (timer !== null) return;
35	
36	  timer = setInterval(() => {
37	    void tick(new Date()).catch((error: unknown) => {
38	      logger.error("scheduler tick failed", {
39	        reason: error instanceof Error ? error.message : String(error),
40	      });
41	    });
42	  }, TICK_INTERVAL_MS);
43	
44	  timer.unref?.();
45	  logger.info("scheduler started", { intervalMs: TICK_INTERVAL_MS });
46	}
47	
48	export function stopScheduler(): void {
49	  if (timer === null) return;
50	  clearInterval(timer);
51	  timer = null;
52	  lastRunAt.clear();
53	}
54	
55	export function isSchedulerRunning(): boolean {
56	  return timer !== null;
57	}
58	
59	/**
60	 * One pass: enqueue whatever cadence says is due, then drain the queue. Split
61	 * out from the interval so tests can drive it with an explicit clock instead
62	 * of waiting a minute.
63	 */
64	export async function tick(now: Date): Promise<void> {
65	  for (const kind of Object.keys(CADENCE_MINUTES) as JobKind[]) {
66	    if (!isDue(kind, now)) continue;
67	
68	    lastRunAt.set(kind, now.getTime());
69	    enqueue({
70	      id: `${kind}:${Math.floor(now.getTime() / 60_000)}`,
71	      kind,
72	      runAt: toIsoTimestamp(now),
73	      attempts: 0,
74	      payload: {},
75	    });
76	  }
77	
78	  const completed = await drain();
79	  if (completed > 0 || pendingCount() > 0) {
80	    logger.debug("tick complete", { completed, pending: pendingCount() });
81	  }
82	}
83	
84	function isDue(kind: JobKind, now: Date): boolean {
85	  const previous = lastRunAt.get(kind);
86	  if (previous === undefined) return true;
87	  return now.getTime() - previous >= CADENCE_MINUTES[kind] * 60_000;
88	}
 1	/**
 2	 * Barrel for the job layer.
 3	 *
 4	 * `instrumentation.ts` imports `startScheduler` from here; everything else in
 5	 * the app talks to jobs by emitting an event, never by calling a runner
 6	 * directly. The individual `run*Job` functions are exported for the admin
 7	 * "run now" action and for the test suite.
 8	 */
 9	export {
10	  drain,
11	  enqueue,
12	  pendingCount,
13	  resetQueue,
14	} from "./queue";
15	export type { JobKind, QueuedJob } from "./queue";
16	
17	export {
18	  isSchedulerRunning,
19	  startScheduler,
20	  stopScheduler,
21	  tick,
22	} from "./scheduler";
23	
24	export { emptyJobResult } from "./types";
25	export type { JobResult } from "./types";
26	
27	export { runCleanupArchivedJob } from "./cleanup-archived-job";
28	export { runDigestEmailJob, shouldRunForOrg } from "./digest-email-job";
29	export { runOverdueIssueJob } from "./overdue-issue-job";
30	export { runSearchReindexJob } from "./search-reindex-job";
31	export { runTrialExpiryJob } from "./trial-expiry-job";
32	export { runUsageRollupJob } from "./usage-rollup-job";
33	export { backoffMs, runWebhookDeliveryJob } from "./webhook-delivery-job";

