    82	    )
    83	    .join("");
    84	
    85	  return [
    86	    `<html><body><h1>${escapeHtml(SUBJECTS[template])}</h1>`,
    87	    `<table>${rows}</table>`,
    88	    "</body></html>",
    89	  ].join("");
    90	}
