     2	 * Shared JSON helpers for the route handlers.
     3	 *
     4	 * Owner D. Every handler under `src/app/api` returns the same envelope as the
     5	 * Server Actions — `{ error: AppErrorShape }` on failure — so a client can use
     6	 * one parser for both. The status code comes from `HTTP_STATUS_BY_CODE`, which
     7	 * is the single mapping from domain error code to HTTP.
     8	 */
     9	
    10	import { HTTP_STATUS_BY_CODE, toAppError } from "@/lib/errors";
    11	import type { AppErrorShape, ApiErrorBody } from "@/types/api";
    12	
    13	/** Turns any thrown value into the JSON error envelope with the right status. */
    14	export function errorResponse(error: unknown): Response {
    15	  const shape: AppErrorShape = toAppError(error);
    16	  const body: ApiErrorBody = { error: shape };
    17	  return Response.json(body, { status: HTTP_STATUS_BY_CODE[shape.code] });
    18	}
    19	
    20	/** Builds the envelope for a failure the handler detected itself. */
    21	export function failure(
    22	  code: AppErrorShape["code"],
    23	  message: string,
    24	): Response {
    25	  const body: ApiErrorBody = { error: { code, message } };
    26	  return Response.json(body, { status: HTTP_STATUS_BY_CODE[code] });
    27	}
